        assert(!runtime.setOutputIntensity(changed_lane, invalid));
      assert(runtime.outputIntensity(changed_lane) == 0.0F);
      assert(runtime.outputIntensity(1U - changed_lane) == 1.0F);
      assert(!runtime.setOutputIntensity(2U, 0.5F));
    }
  }
}

